  "Inserted \"{name}\" ({format}, {duration}, mixed down to mono)": "Wstawiono „{name}” ({format}, {duration}, uśrednione do mono)",
  "Inserted \"{name}\" ({format}, {duration})": "Wstawiono „{name}” ({format}, {duration})",
